invocation:
it.each([
		{
			name: "webSearch",
			toolCase: "webSearchToolCall",
			messageType: "user",
			uuid: "agent-1:7",
			args: { searchTerm: "Cursor IDE", toolCallId: "tool-1" },
			value: {
				references: [{
					title: "Web search results",
					url: "",
					chunk: "Links:\n1. [Cursor — Build Software with AI Agents](https://cursor.com/product)",
				}],
			},
			identity: "cursor-transcript:agent-1:7:webSearch:tool-1",
			text: "Links:\n1. [Cursor — Build Software with AI Agents](https://cursor.com/product)",
		},
		{
			name: "webFetch",
			toolCase: "webFetchToolCall",
			messageType: "assistant",
			uuid: "agent-1:8",
			args: { url: "https://example.com", toolCallId: "tool-fetch-1" },
			value: { content: [{ type: "text", text: "<title>Example Domain</title>" }] },
			identity: "cursor-transcript:agent-1:8:webFetch:tool-fetch-1",
			text: "<title>Example Domain</title>",
		},
	] as const)

it.each([
		{ name: "default zero rates", cost: undefined, expectedCost: 0 },
		{ name: "configured rates", cost: { input: 2, output: 10, cacheRead: 0.2, cacheWrite: 2.5 }, expectedCost: 0.0071 },
		{
			name: "native request-wide tier",
			cost: {
				input: 1, output: 1, cacheRead: 1, cacheWrite: 1,
				tiers: [{ inputTokensAbove: 9999, input: 2, output: 10, cacheRead: 0.2, cacheWrite: 2.5 }],
			},
			expectedCost: 0.0071,
		},
	])

it.each([
		{
			name: "grep",
			args: { pattern: "sidebar", path: "src" },
			result: { matches: ["src/a.css"] },
			expected: { name: "grep", arguments: { pattern: "sidebar", path: "src" } },
		},
		{
			name: "task",
			args: { description: "Verify plan-strip resync" },
			result: { result: { success: { command: "echo ok", stdout: "ok\n" } } },
			expected: { name: "cursor", arguments: { activityTitle: "Cursor subagent", activitySummary: "Verify plan-strip resync: $ echo ok" } },
		},
	])

it.each([
		["run metadata", {
			id: "run-abc123456789", status: "error", result: "Cursor SDK run failed",
			durationMs: 900, model: { id: "composer-2.5" },
		}, ["model composer-2.5", "900ms"]],
		["explicit SDK detail", {
			id: "run-1", status: "error", result: "MCP tool call timed out after 60s",
		}, ["MCP tool call timed out after 60s"]],
	] as const)

it.each([
		{
			modelId: "gpt-5.5@1m", reasoning: "medium", supportsThinking: true,
			selection: { id: "gpt-5.5", params: [
				{ id: "context", value: "1m" }, { id: "fast", value: "false" }, { id: "reasoning", value: "medium" },
			] },
		},
		{
			modelId: "gpt-5.5@272k", reasoning: "xhigh", supportsThinking: true,
			selection: { id: "gpt-5.5", params: [
				{ id: "context", value: "272k" }, { id: "fast", value: "false" }, { id: "reasoning", value: "extra-high" },
			] },
		},
		{
			modelId: "claude-opus-4-7@1m", reasoning: "xhigh", supportsThinking: true,
			selection: { id: "claude-opus-4-7", params: [
				{ id: "context", value: "1m" }, { id: "effort", value: "xhigh" }, { id: "thinking", value: "true" },
			] },
		},
		{
			modelId: "claude-sonnet-4-6@1m", reasoning: undefined, supportsThinking: true,
			selection: { id: "claude-sonnet-4-6", params: [
				{ id: "context", value: "1m" }, { id: "thinking", value: "false" },
			] },
		},
		{
			modelId: "gemini-3.1-pro", reasoning: undefined, supportsThinking: false,
			selection: { id: "gemini-3.1-pro" },
		},
	] as const)

it.each([
		{
			label: "direct require calls",
			uses: [
				'class NamedLoader extends require("../shared/helper.mjs").default {}',
				'class DirectLoader extends createRequire(import.meta.url)("../shared/helper.mjs").default {}',
			],
			messages: [
				"require created by createRequire may only be used via require.resolve",
				"createRequire may only initialize a named resolve-only loader",
			],
		},
		{
			label: "aliases",
			uses: ['const alias = require;', 'alias("../shared/helper.mjs");'],
			messages: ["require created by createRequire may only be used via require.resolve"],
		},
	])

it.each([
		[
			"closed-writable lookalike without Cursor SDK provenance",
			`const error = new Error("WritableIterable is closed");
error.name = "WriteIterableClosedError";
error.stack = "WriteIterableClosedError: WritableIterable is closed\\n    at write (/repo/src/stream.js:1:1)";
Promise.reject(error);`,
			"WritableIterable is closed",
		],
		["unrelated rejection", `Promise.reject(new Error("unrelated delayed failure"));`, "unrelated delayed failure"],
	])

it.each([
		{
			name: "plans initial bootstrap without resetting the agent",
			state: { bootstrapped: false, contextFingerprint: "", incrementalSendCount: 0 },
			context: priorContext,
			expected: { mode: "bootstrap", resetAgent: false, reason: "initial" },
		},
		{
			name: "plans incremental sends below the rebootstrap threshold",
			state: { bootstrapped: true, contextFingerprint: fingerprint, incrementalSendCount: MAX_COMPLETED_INCREMENTAL_SENDS_BEFORE_REBOOTSTRAP - 1 },
			context: followUpContext,
			expected: { mode: "incremental", resetAgent: false, reason: "incremental" },
		},
		{
			name: "plans agent reset and bootstrap at the incremental threshold",
			state: { bootstrapped: true, contextFingerprint: fingerprint, incrementalSendCount: MAX_COMPLETED_INCREMENTAL_SENDS_BEFORE_REBOOTSTRAP },
			context: followUpContext,
			expected: { mode: "bootstrap", resetAgent: true, reason: "incremental_threshold" },
		},
		{
			name: "plans context-divergence bootstrap with agent reset",
			state: { bootstrapped: true, contextFingerprint: fingerprint, incrementalSendCount: 2 },
			context: { messages: [{ role: "user", content: "Hello edited", timestamp: 1 }] } satisfies Context,
			expected: { mode: "bootstrap", resetAgent: true, reason: "context_divergence" },
		},
	])
